{
  "name": "SolaMeme AI Launcher",
  "description": "An AI-powered Solana memecoin creator that scans for trends, designs assets, and simulates deployment with liquidity management."
}

export interface Trend {
  topic: string;
  description: string;
  volume: string;
}

export interface CoinDraft {
  name: string;
  ticker: string;
  description: string;
  story: string;
  imagePrompt: string;
  imageBase64: string | null;
}

export interface Tokenomics {
  supply: number;
  liquidityEth: number; // Stored as SOL value
  buyTax: number;
  sellTax: number;
}

export enum Step {
  TRENDS = 1,
  DESIGN = 2,
  CONFIG = 3,
  DEPLOY = 4,
  SUCCESS = 5
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI, Type, SchemaType } from "@google/genai";
import { Trend, CoinDraft } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Scans for trending topics using Google Search grounding
 */
export const scanTrendingTopics = async (): Promise<Trend[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: "Find 5 current, viral, and funny trending topics on the internet right now that would make good memecoins. Focus on pop culture, tech fails, or viral animals.",
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              topic: { type: Type.STRING },
              description: { type: Type.STRING },
              volume: { type: Type.STRING, description: "Estimated hype level e.g. 'High', 'Viral'" },
            },
            required: ["topic", "description", "volume"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text) as Trend[];
  } catch (error) {
    console.error("Error scanning trends:", error);
    // Fallback data in case of API or search failure
    return [
      { topic: "SpaceX Starship", description: "The rocket that keeps exploding but we love it.", volume: "High" },
      { topic: "Moo Deng", description: "The viral pygmy hippo causing chaos.", volume: "Viral" },
      { topic: "AI Hallucinations", description: "When the robots get it wrong.", volume: "Medium" },
    ];
  }
};

/**
 * Generates initial coin details based on a topic
 */
export const generateCoinDetails = async (topic: string, additionalContext: string = ""): Promise<Partial<CoinDraft>> => {
  const prompt = `
    Create a concept for a Solana memecoin based on the topic: "${topic}".
    Context: ${additionalContext}.
    Return a JSON object with a creative Name, a 3-5 letter Ticker, a funny Description, a short 'Story' or lore, and a detailed Image Generation Prompt for the logo.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          ticker: { type: Type.STRING },
          description: { type: Type.STRING },
          story: { type: Type.STRING },
          imagePrompt: { type: Type.STRING },
        },
        required: ["name", "ticker", "description", "story", "imagePrompt"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("Failed to generate coin details");
  return JSON.parse(text) as Partial<CoinDraft>;
};

/**
 * Generates an image for the coin logo
 */
export const generateCoinImage = async (prompt: string): Promise<string> => {
  // Enhanced prompt for better logo results
  const enhancedPrompt = `A high quality, vector art style, circular crypto logo sticker. ${prompt}. Vibrant colors, clean lines, white background.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-image",
    contents: {
      parts: [{ text: enhancedPrompt }],
    },
    config: {
      imageConfig: {
          aspectRatio: "1:1",
      },
    },
  });

  // Extract image
  let base64String = "";
  if (response.candidates && response.candidates[0].content && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
              base64String = part.inlineData.data;
              break;
          }
      }
  }

  if (!base64String) throw new Error("No image generated");
  return `data:image/png;base64,${base64String}`;
};

/**
 * Refines text based on chat
 */
export const refineCoinDetails = async (currentDraft: CoinDraft, userInstruction: string): Promise<Partial<CoinDraft>> => {
  const prompt = `
    Current Coin: ${JSON.stringify(currentDraft)}.
    User Instruction: ${userInstruction}.
    Update the Name, Ticker, Description, or Story based on the instruction. If a field doesn't need changing, keep it the same.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          ticker: { type: Type.STRING },
          description: { type: Type.STRING },
          story: { type: Type.STRING },
        },
        required: ["name", "ticker", "description", "story"],
      },
    },
  });

  const text = response.text;
  return JSON.parse(text!) as Partial<CoinDraft>;
};

import React, { useEffect, useState } from 'react';
import { Trend } from '../types';
import { scanTrendingTopics } from '../services/geminiService';
import { Sparkles, TrendingUp, Search, Loader2 } from 'lucide-react';

interface Props {
  onSelectTrend: (trend: string) => void;
}

const TrendScanner: React.FC<Props> = ({ onSelectTrend }) => {
  const [trends, setTrends] = useState<Trend[]>([]);
  const [loading, setLoading] = useState(true);
  const [customTopic, setCustomTopic] = useState('');

  useEffect(() => {
    let mounted = true;
    const fetchTrends = async () => {
      try {
        const data = await scanTrendingTopics();
        if (mounted) {
          setTrends(data);
          setLoading(false);
        }
      } catch (err) {
        console.error(err);
        if (mounted) setLoading(false);
      }
    };
    fetchTrends();
    return () => { mounted = false; };
  }, []);

  return (
    <div className="w-full max-w-4xl mx-auto p-6 animate-fade-in">
      <div className="text-center mb-10">
        <h2 className="text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-pink-600 mb-4">
          Market Trend Scanner
        </h2>
        <p className="text-slate-400">
          Our AI agents are scanning the blockchain and social web for the next viral hit.
        </p>
      </div>

      <div className="mb-8">
        <div className="flex gap-4">
          <input
            type="text"
            placeholder="Or enter your own idea..."
            value={customTopic}
            onChange={(e) => setCustomTopic(e.target.value)}
            className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-6 py-4 text-white focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all"
          />
          <button
            onClick={() => customTopic && onSelectTrend(customTopic)}
            disabled={!customTopic}
            className="bg-purple-600 hover:bg-purple-500 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-4 rounded-xl font-bold transition-all flex items-center gap-2"
          >
            Create <Sparkles className="w-5 h-5" />
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 space-y-4">
          <Loader2 className="w-12 h-12 text-purple-500 animate-spin" />
          <p className="text-slate-500 animate-pulse">Analyzing social signals...</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {trends.map((trend, idx) => (
            <button
              key={idx}
              onClick={() => onSelectTrend(trend.topic)}
              className="group bg-slate-800/50 hover:bg-slate-800 border border-slate-700 hover:border-purple-500/50 rounded-2xl p-6 text-left transition-all duration-300 hover:-translate-y-1 relative overflow-hidden"
            >
              <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity">
                <TrendingUp className="w-24 h-24 text-purple-500 transform rotate-12" />
              </div>

              <div className="relative z-10">
                <div className="inline-block px-3 py-1 rounded-full bg-purple-500/10 text-purple-400 text-xs font-bold mb-3 border border-purple-500/20">
                  {trend.volume.toUpperCase()} VOLUME
                </div>
                <h3 className="text-xl font-bold text-white mb-2">{trend.topic}</h3>
                <p className="text-slate-400 text-sm">{trend.description}</p>
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default TrendScanner;

import React, { useState, useEffect, useRef } from 'react';
import { CoinDraft, ChatMessage } from '../types';
import { generateCoinDetails, generateCoinImage, refineCoinDetails } from '../services/geminiService';
import { Send, RefreshCw, CheckCircle, Wand2, Image as ImageIcon } from 'lucide-react';

interface Props {
  initialTopic: string;
  onComplete: (draft: CoinDraft) => void;
}

const CoinDesigner: React.FC<Props> = ({ initialTopic, onComplete }) => {
  const [draft, setDraft] = useState<CoinDraft>({
    name: '',
    ticker: '',
    description: '',
    story: '',
    imagePrompt: '',
    imageBase64: null
  });
  const [loading, setLoading] = useState(true);
  const [generatingImage, setGeneratingImage] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Initial generation
  useEffect(() => {
    const init = async () => {
      setMessages([{ role: 'model', text: `Analyzing "${initialTopic}" and generating coin concepts...` }]);
      try {
        const details = await generateCoinDetails(initialTopic);
        setDraft(prev => ({ ...prev, ...details }));
        setMessages(prev => [
          ...prev, 
          { role: 'model', text: `I've drafted a concept for ${details.name} ($${details.ticker}). How does it look? We can tweak the details or generate the artwork.` }
        ]);
        setLoading(false);
      } catch (e) {
        console.error(e);
        setLoading(false);
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);

    // Optimistic UI for loading
    setMessages(prev => [...prev, { role: 'model', text: 'Thinking...' }]);

    try {
        const newDetails = await refineCoinDetails(draft, userMsg);
        setDraft(prev => ({ ...prev, ...newDetails }));
        setMessages(prev => {
            const newArr = [...prev];
            newArr[newArr.length - 1] = { role: 'model', text: `Updated! Now we have ${newDetails.name || draft.name}. Anything else or shall we generate the logo?` };
            return newArr;
        });
    } catch (e) {
        console.error(e);
        setMessages(prev => {
             const newArr = [...prev];
             newArr[newArr.length - 1] = { role: 'model', text: "Sorry, I had trouble updating the details. Try again?" };
             return newArr;
        });
    }
  };

  const handleGenerateImage = async () => {
    setGeneratingImage(true);
    try {
      const b64 = await generateCoinImage(draft.imagePrompt || `${draft.name} meme coin logo`);
      setDraft(prev => ({ ...prev, imageBase64: b64 }));
    } catch (e) {
      console.error("Image generation failed", e);
      alert("Failed to generate image. Please try again.");
    } finally {
      setGeneratingImage(false);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8 p-6 h-[80vh]">
      {/* Left: Chat & Details */}
      <div className="flex flex-col bg-slate-800 rounded-2xl border border-slate-700 overflow-hidden shadow-2xl">
        <div className="bg-slate-900 p-4 border-b border-slate-700 flex justify-between items-center">
            <h3 className="font-bold flex items-center gap-2"><Wand2 className="w-4 h-4 text-purple-400"/> AI Designer Assistant</h3>
        </div>

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm ${
                m.role === 'user' 
                  ? 'bg-purple-600 text-white rounded-br-none' 
                  : 'bg-slate-700 text-slate-200 rounded-bl-none'
              }`}>
                {m.text}
              </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        {/* Input */}
        <div className="p-4 bg-slate-900 border-t border-slate-700 flex gap-2">
          <input
            className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white focus:outline-none focus:border-purple-500"
            placeholder="e.g. Make the name funnier..."
            value={chatInput}
            onChange={e => setChatInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
            disabled={loading}
          />
          <button 
            onClick={handleSendMessage}
            className="p-3 bg-purple-600 rounded-xl hover:bg-purple-500 text-white transition-colors"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Right: Preview & Actions */}
      <div className="flex flex-col gap-6">

        {/* Card Preview */}
        <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-32 bg-purple-600/20 blur-[100px] rounded-full -mr-16 -mt-16 pointer-events-none"></div>

            <div className="flex flex-col items-center text-center relative z-10">
                <div className="w-48 h-48 mb-6 rounded-full bg-slate-900 border-4 border-slate-700 flex items-center justify-center relative overflow-hidden shadow-2xl">
                    {draft.imageBase64 ? (
                        <img src={draft.imageBase64} alt="Coin Logo" className="w-full h-full object-cover" />
                    ) : (
                        <div className="text-slate-600 flex flex-col items-center">
                            <ImageIcon className="w-12 h-12 mb-2" />
                            <span className="text-xs">No Image</span>
                        </div>
                    )}
                    {generatingImage && (
                        <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                            <Loader2 className="w-8 h-8 text-white animate-spin" />
                        </div>
                    )}
                </div>

                {loading ? (
                    <div className="w-full space-y-3 animate-pulse">
                        <div className="h-8 bg-slate-700 rounded w-1/2 mx-auto"></div>
                        <div className="h-4 bg-slate-700 rounded w-1/4 mx-auto"></div>
                        <div className="h-16 bg-slate-700 rounded w-full"></div>
                    </div>
                ) : (
                    <>
                        <h2 className="text-3xl font-bold text-white mb-1">{draft.name || 'Unnamed Coin'}</h2>
                        <div className="inline-block px-3 py-1 bg-purple-900/50 text-purple-300 rounded-full text-sm font-mono mb-4 border border-purple-500/30">
                            ${draft.ticker || 'TICKER'}
                        </div>
                        <p className="text-slate-300 text-sm mb-4 leading-relaxed max-w-md">
                            {draft.description}
                        </p>
                        <div className="bg-slate-900/50 p-3 rounded-lg w-full text-left">
                            <span className="text-xs uppercase text-slate-500 font-bold block mb-1">Story / Lore</span>
                            <p className="text-xs text-slate-400 italic">"{draft.story}"</p>
                        </div>
                    </>
                )}
            </div>
        </div>

        {/* Action Buttons */}
        <div className="grid grid-cols-2 gap-4">
            <button
                onClick={handleGenerateImage}
                disabled={loading || generatingImage || !draft.name}
                className="bg-slate-700 hover:bg-slate-600 text-white p-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-colors border border-slate-600"
            >
                <RefreshCw className={`w-5 h-5 ${generatingImage ? 'animate-spin' : ''}`} />
                {draft.imageBase64 ? 'Regenerate Art' : 'Generate Art'}
            </button>
            <button
                onClick={() => onComplete(draft)}
                disabled={!draft.imageBase64 || !draft.name}
                className="bg-green-500 hover:bg-green-400 disabled:bg-slate-700 disabled:text-slate-500 text-black p-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-colors"
            >
                <CheckCircle className="w-5 h-5" />
                Proceed to Deploy
            </button>
        </div>
      </div>
    </div>
  );
};

export default CoinDesigner;

