import { GoogleGenAI, Type } from "@google/genai";
import { Trend, CoinDraft } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Scans for trending topics using Google Search grounding
 */
export const scanTrendingTopics = async (): Promise<Trend[]> => {
  try {
    // When using googleSearch, we cannot use responseSchema or responseMimeType.
    // We must prompt the model to return JSON as text and then parse it.
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: "Find 5 current, viral, and funny trending topics on the internet right now that would make good memecoins. Focus on pop culture, tech fails, or viral animals. Return the output as a valid JSON array of objects with keys: 'topic', 'description', 'volume' (e.g., 'High', 'Viral'). Do not wrap the JSON in markdown code blocks.",
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    let text = response.text;
    if (!text) return [];

    // Clean potential markdown formatting
    text = text.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '').trim();

    return JSON.parse(text) as Trend[];
  } catch (error) {
    console.error("Error scanning trends:", error);
    // Fallback data in case of API or search failure
    return [
      { topic: "SpaceX Starship", description: "The rocket that keeps exploding but we love it.", volume: "High" },
      { topic: "Moo Deng", description: "The viral pygmy hippo causing chaos.", volume: "Viral" },
      { topic: "AI Hallucinations", description: "When the robots get it wrong.", volume: "Medium" },
    ];
  }
};

/**
 * Generates initial coin details based on a topic
 */
export const generateCoinDetails = async (topic: string, additionalContext: string = ""): Promise<Partial<CoinDraft>> => {
  const prompt = `
    Create a concept for a Solana memecoin based on the topic: "${topic}".
    Context: ${additionalContext}.
    Return a JSON object with a creative Name, a 3-5 letter Ticker, a funny Description, a short 'Story' or lore, and a detailed Image Generation Prompt for the logo.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          ticker: { type: Type.STRING },
          description: { type: Type.STRING },
          story: { type: Type.STRING },
          imagePrompt: { type: Type.STRING },
        },
        required: ["name", "ticker", "description", "story", "imagePrompt"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("Failed to generate coin details");
  return JSON.parse(text) as Partial<CoinDraft>;
};

/**
 * Generates an image for the coin logo
 */
export const generateCoinImage = async (prompt: string): Promise<string> => {
  // Enhanced prompt for better logo results
  const enhancedPrompt = `A high quality, vector art style, circular crypto logo sticker. ${prompt}. Vibrant colors, clean lines, white background.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-image",
    contents: {
      parts: [{ text: enhancedPrompt }],
    },
    config: {
      imageConfig: {
          aspectRatio: "1:1",
      },
    },
  });

  // Extract image
  let base64String = "";
  if (response.candidates && response.candidates[0].content && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
              base64String = part.inlineData.data;
              break;
          }
      }
  }

  if (!base64String) throw new Error("No image generated");
  return `data:image/png;base64,${base64String}`;
};

/**
 * Refines text based on chat
 */
export const refineCoinDetails = async (currentDraft: CoinDraft, userInstruction: string): Promise<Partial<CoinDraft>> => {
  const prompt = `
    Current Coin: ${JSON.stringify(currentDraft)}.
    User Instruction: ${userInstruction}.
    Update the Name, Ticker, Description, or Story based on the instruction. If a field doesn't need changing, keep it the same.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          ticker: { type: Type.STRING },
          description: { type: Type.STRING },
          story: { type: Type.STRING },
        },
        required: ["name", "ticker", "description", "story"],
      },
    },
  });

  const text = response.text;
  return JSON.parse(text!) as Partial<CoinDraft>;
};

