/**
 * Generates marketing assets (Website copy & Tweet)
 */
export const generateMarketingKit = async (draft: CoinDraft): Promise<MarketingAssets> => {
  const prompt = `
    Create a marketing kit for the memecoin: ${draft.name} ($${draft.ticker}).
    Description: ${draft.description}.

    1. A catchy, viral, short Headline for a landing page.
    2. A funny Tagline.
    3. 3 bullet points explaining why people should buy (use meme humor).
    4. A viral Tweet text (max 280 chars) with hashtags.
    5. A color theme hex codes (primary, background, accent) that matches the vibe.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          headline: { type: Type.STRING },
          tagline: { type: Type.STRING },
          bulletPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
          tweetText: { type: Type.STRING },
          colorTheme: {
            type: Type.OBJECT,
            properties: {
              primary: { type: Type.STRING },
              background: { type: Type.STRING },
              accent: { type: Type.STRING },
            },
            required: ["primary", "background", "accent"]
          }
        },
        required: ["headline", "tagline", "bulletPoints", "tweetText", "colorTheme"],
      },
    },
  });

  const text = response.text;
  return JSON.parse(text!) as MarketingAssets;
};

