import React, { useEffect, useState } from 'react';
import { CoinDraft, Tokenomics } from '../types';
import { Check, Terminal, ExternalLink, Globe, Shield, Bot } from 'lucide-react';

interface Props {
  draft: CoinDraft;
  tokenomics: Tokenomics;
  onReset: () => void;
}

const LaunchPad: React.FC<Props> = ({ draft, tokenomics, onReset }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [completed, setCompleted] = useState(false);
  const [address, setAddress] = useState('');

  const addLog = (msg: string) => setLogs(prev => [...prev, `> ${msg}`]);

  const isSolana = tokenomics.network === 'solana';
  const currency = isSolana ? 'SOL' : 'POL';
  const explorerName = isSolana ? 'Solscan' : 'PolygonScan';
  const dexName = tokenomics.launchMode === 'bonding' ? 'Pump.fun' : (isSolana ? 'Raydium' : 'QuickSwap');

  useEffect(() => {
    // Generate a mock address based on network
    let mockAddr = '';
    if (isSolana) {
       const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
       for (let i = 0; i < 44; i++) mockAddr += chars.charAt(Math.floor(Math.random() * chars.length));
    } else {
       // Polygon (EVM) address
       const hex = '0123456789abcdef';
       mockAddr = '0x';
       for (let i = 0; i < 40; i++) mockAddr += hex.charAt(Math.floor(Math.random() * hex.length));
    }
    setAddress(mockAddr);

    const sequence = async () => {
      addLog(`Initializing ${tokenomics.network.toUpperCase()} deployment sequence...`);
      await new Promise(r => setTimeout(r, 800));

      const networkName = isSolana ? "Solana Mainnet-Beta" : "Polygon PoS Mainnet";
      addLog(`Connecting to ${networkName}...`);
      await new Promise(r => setTimeout(r, 1000));

      // Metadata
      addLog(`Uploading metadata for ${draft.name} ($${draft.ticker})...`);
      addLog(`Metadata Hash: ${isSolana ? 'ipfs://' : '0x'}${mockAddr.substring(0, 12)}...`);
      await new Promise(r => setTimeout(r, 1500));

      // AI VERIFICATION STEP
      addLog(`--- INITIATING AI SMART CONTRACT AUDIT ---`);
      await new Promise(r => setTimeout(r, 800));
      addLog(`AI Agent scanning contract code...`);
      await new Promise(r => setTimeout(r, 1200));
      addLog(`Checking for honeypot logic... [SAFE]`);
      await new Promise(r => setTimeout(r, 500));
      addLog(`Verifying Mint Authority revocation... [VERIFIED]`);
      await new Promise(r => setTimeout(r, 500));
      addLog(`Analyzing gas optimization... [OPTIMIZED]`);
      await new Promise(r => setTimeout(r, 800));
      addLog(`AUDIT COMPLETE: Score 100/100 (Safe)`);
      addLog(`------------------------------------------`);
      await new Promise(r => setTimeout(r, 1000));


      if (tokenomics.launchMode === 'bonding') {
        // Bonding Curve Logic (Solana specific usually)
        addLog(`Initiating Bonding Curve Deployment...`);
        await new Promise(r => setTimeout(r, 1000));
        addLog(`Deploying to Pump.fun protocol...`);
        await new Promise(r => setTimeout(r, 1500));
        addLog(`Minting ${tokenomics.supply.toLocaleString()} tokens to Curve...`);
      } else {
        // DEX Logic (Raydium or QuickSwap)
        const contractType = isSolana ? "SPL Token" : "ERC-20 Contract";
        addLog(`Deploying ${contractType}...`);
        await new Promise(r => setTimeout(r, 1000));
        addLog(`Minting ${tokenomics.supply.toLocaleString()} tokens...`);

        await new Promise(r => setTimeout(r, 1000));
        addLog(`Creating ${dexName} Liquidity Pool (${currency}/${draft.ticker})...`);
        addLog(`Adding ${tokenomics.liquidity} ${currency} to pool...`);
        await new Promise(r => setTimeout(r, 2000));
        addLog("Locking LP tokens...");
      }

      await new Promise(r => setTimeout(r, 800));
      addLog("Verifying contract...");
      addLog("DEPLOYMENT SUCCESSFUL!");
      setCompleted(true);
    };

    sequence();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="w-full max-w-3xl mx-auto p-6 animate-fade-in">
      {!completed ? (
        <div className="bg-black rounded-xl p-6 font-mono text-sm h-96 overflow-y-auto border border-slate-800 shadow-2xl relative">
          <div className="absolute top-0 right-0 p-4 flex gap-2">
             <Bot className="w-6 h-6 text-purple-500 animate-pulse" />
             <Terminal className="w-6 h-6 text-green-500 animate-pulse" />
          </div>
          {logs.map((log, i) => (
            <div key={i} className={`mb-2 font-bold tracking-wide ${log.includes("AUDIT") || log.includes("AI Agent") ? 'text-purple-400' : 'text-green-400'}`}>
              {log}
            </div>
          ))}
          <div className="w-3 h-5 bg-green-500 inline-block animate-pulse ml-2" />
        </div>
      ) : (
        <div className="text-center space-y-8 animate-fade-in-up">
          <div className={`w-24 h-24 rounded-full flex items-center justify-center mx-auto shadow-[0_0_50px_rgba(34,197,94,0.5)] ${isSolana ? 'bg-green-500' : 'bg-violet-500'}`}>
            <Check className="w-12 h-12 text-black" />
          </div>

          <div>
            <div className="flex items-center justify-center gap-2 mb-2">
                <Shield className="w-6 h-6 text-green-500" />
                <span className="text-green-500 font-bold tracking-widest text-sm uppercase">AI Verified Contract</span>
            </div>
            <h1 className="text-5xl font-bold text-white mb-2">Token Live!</h1>
            <p className="text-xl text-slate-400">Your memecoin is now trading on {tokenomics.network.charAt(0).toUpperCase() + tokenomics.network.slice(1)}.</p>
          </div>

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 max-w-lg mx-auto">
            <div className="flex items-center gap-4 mb-4">
              {draft.imageBase64 && <img src={draft.imageBase64} className="w-16 h-16 rounded-full" />}
              <div className="text-left">
                <div className="text-white font-bold text-xl">{draft.name}</div>
                <div className="text-purple-400 font-mono">${draft.ticker}</div>
              </div>
            </div>

            <div className="bg-black/50 p-3 rounded-lg flex items-center justify-between font-mono text-sm text-slate-300 mb-4">
              <span className="truncate w-64">{address}</span>
              <button className="text-purple-400 hover:text-purple-300 font-bold">COPY</button>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <button className="bg-slate-700 hover:bg-slate-600 text-white py-3 rounded-lg flex items-center justify-center gap-2">
                    <Globe className="w-4 h-4" /> View on {explorerName}
                </button>
                <button className={`text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 ${
                    isSolana 
                        ? 'bg-green-600 hover:bg-green-500 text-black' 
                        : 'bg-violet-600 hover:bg-violet-500'
                }`}>
                    <ExternalLink className="w-4 h-4" /> Trade on {dexName}
                </button>
            </div>
          </div>

          <button 
            onClick={onReset}
            className="text-slate-500 hover:text-white transition-colors"
          >
            Launch Another Coin
          </button>
        </div>
      )}
    </div>
  );
};

export default LaunchPad;

import React, { useState } from 'react';
import { Step, CoinDraft, Tokenomics } from './types';
import TrendScanner from './components/TrendScanner';
