import { Rocket, Wallet, Wifi } from 'lucide-react';

const App: React.FC = () => {
  const [step, setStep] = useState<Step>(Step.TRENDS);
  const [selectedTopic, setSelectedTopic] = useState<string>('');
  const [draft, setDraft] = useState<CoinDraft | null>(null);
  const [tokenomics, setTokenomics] = useState<Tokenomics | null>(null);
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [isConnecting, setIsConnecting] = useState(false);

  const handleConnectWallet = async () => {
    setIsConnecting(true);
    // Simulate wallet connection delay
    await new Promise(resolve => setTimeout(resolve, 1000));
    // Generate mock SOL address
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let addr = '8'; // Solana addrs often start with numbers/letters
    for (let i = 0; i < 4; i++) addr += chars.charAt(Math.floor(Math.random() * chars.length));
    addr += '...';
    for (let i = 0; i < 4; i++) addr += chars.charAt(Math.floor(Math.random() * chars.length));

    setWalletAddress(addr);
    setIsConnecting(false);
  };

  const handleTrendSelect = (topic: string) => {
    setSelectedTopic(topic);
    setStep(Step.DESIGN);
  };

  const handleDesignComplete = (completedDraft: CoinDraft) => {
    setDraft(completedDraft);
    setStep(Step.CONFIG);
  };

  const handleDeploy = (config: Tokenomics) => {
    setTokenomics(config);
    setStep(Step.DEPLOY);
  };

  const handleReset = () => {
    setStep(Step.TRENDS);
    setSelectedTopic('');
    setDraft(null);
    setTokenomics(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-[#0f172a] to-slate-900 text-white selection:bg-purple-500 selection:text-white flex flex-col">
