        <div className="max-w-7xl mx-auto flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-gradient-to-tr from-purple-600 to-pink-500 rounded-xl flex items-center justify-center shadow-lg shadow-purple-500/20">
                    <Rocket className="text-white w-6 h-6" />
                </div>
                <h1 className="text-xl font-bold tracking-tight hidden md:block">SolaMeme <span className="text-purple-400 font-normal">AI</span></h1>
            </div>

            {/* Status Bar */}
            <div className="hidden md:flex items-center gap-2 bg-slate-800/50 px-3 py-1 rounded-full border border-slate-700/50">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                <span className="text-xs font-mono text-green-400 font-bold uppercase tracking-wider">Pump.fun Systems: Online</span>
            </div>

            <div className="flex items-center gap-4">
                <button 
                  onClick={walletAddress ? () => {} : handleConnectWallet}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg font-bold transition-all border ${
                    walletAddress 
                      ? 'bg-slate-800 border-slate-700 text-purple-400 cursor-default' 
                      : 'bg-purple-600 hover:bg-purple-500 border-purple-500 text-white shadow-lg shadow-purple-900/20'
                  }`}
                >
                  <Wallet className="w-4 h-4" />
                  {isConnecting ? 'Connecting...' : (walletAddress || 'Connect Wallet')}
                </button>
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center p-4">
        {step === Step.TRENDS && (
          <TrendScanner onSelectTrend={handleTrendSelect} />
        )}

        {step === Step.DESIGN && (
          <CoinDesigner 
            initialTopic={selectedTopic} 
            onComplete={handleDesignComplete} 
          />
        )}

        {step === Step.CONFIG && draft && (
          <DeployConfig 
            draft={draft} 
            onDeploy={handleDeploy} 
            onBack={() => setStep(Step.DESIGN)} 
            walletAddress={walletAddress}
            onConnectWallet={handleConnectWallet}
          />
        )}

        {step === Step.DEPLOY && draft && tokenomics && (
          <LaunchPad 
            draft={draft} 
            tokenomics={tokenomics} 
            onReset={handleReset} 
            walletAddress={walletAddress}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="p-6 text-center text-slate-600 text-sm border-t border-slate-800 flex justify-center items-center gap-4">
        <p>Powered by Gemini 2.5 Flash & Solana Blockchain</p>
        <span className="text-slate-800">|</span>
        <div className="flex items-center gap-2 text-green-500/50 text-xs font-mono">
            <Wifi className="w-3 h-3" /> Pump.fun API Connected
        </div>
      </footer>
    </div>
  );
};

