}

const DeployConfig: React.FC<Props> = ({ draft, onDeploy, onBack, walletAddress, onConnectWallet }) => {
  const [activeTab, setActiveTab] = useState<'config' | 'marketing'>('config');

  // Config State
  const [network, setNetwork] = useState<NetworkId>('solana');
  const [launchMode, setLaunchMode] = useState<LaunchMode>('bonding');
  const [supply, setSupply] = useState(1000000000);
  const [liquidity, setLiquidity] = useState(5); 
  const [buyTax, setBuyTax] = useState(0);
  const [sellTax, setSellTax] = useState(0);

  // Marketing State
  const [marketing, setMarketing] = useState<MarketingAssets | null>(null);
  const [generatingMarketing, setGeneratingMarketing] = useState(false);

  const currencySymbol = network === 'solana' ? 'SOL' : 'POL';

  // Auto-adjust defaults when switching modes or networks
  useEffect(() => {
    if (network === 'polygon') {
      setLaunchMode('dex');
      setLiquidity(100);
    } else {
      setLaunchMode('bonding');
      setLiquidity(0);
    }
  }, [network]);

  useEffect(() => {
    if (launchMode === 'bonding') {
      setSupply(1000000000); 
      setLiquidity(0);
    } else {
      if (liquidity === 0) setLiquidity(network === 'solana' ? 5 : 100);
    }
  }, [launchMode, network]);

  const handleGenerateMarketing = async () => {
    setGeneratingMarketing(true);
    try {
      const assets = await generateMarketingKit(draft);
      setMarketing(assets);
