                        >
                            <Twitter className="w-4 h-4" /> Share Alpha
                        </button>
                    </div>
                </div>

                <button 
                    onClick={onReset}
                    className="w-full text-slate-500 hover:text-white transition-colors text-sm"
                >
                    Launch Another Coin
                </button>
            </div>

            {/* Right: Live Trading Feed */}
            <div className="bg-slate-900 rounded-xl border border-slate-800 overflow-hidden flex flex-col h-full shadow-2xl">
