import React, { useState, useEffect } from 'react';
import { Step, CoinDraft, Tokenomics, PhantomProvider } from './types';
import TrendScanner from './components/TrendScanner';
import CoinDesigner from './components/CoinDesigner';
import DeployConfig from './components/DeployConfig';
import LaunchPad from './components/LaunchPad';
import { Rocket, Wallet, Wifi, Server, Activity, Ghost, LogOut } from 'lucide-react';

const App: React.FC = () => {
  const [step, setStep] = useState<Step>(Step.TRENDS);
  const [selectedTopic, setSelectedTopic] = useState<string>('');
  const [draft, setDraft] = useState<CoinDraft | null>(null);
  const [tokenomics, setTokenomics] = useState<Tokenomics | null>(null);

  // Wallet State
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const [phantomProvider, setPhantomProvider] = useState<PhantomProvider | null>(null);

  // Check for Phantom on mount
  useEffect(() => {
    if ('solana' in window) {
      const provider = window.solana;
      if (provider?.isPhantom) {
        setPhantomProvider(provider);
        // Optional: Eagerly connect if trusted
        // provider.connect({ onlyIfTrusted: true })
        //   .then((resp) => setWalletAddress(resp.publicKey.toString()))
        //   .catch(() => {});
      }
    }
  }, []);

  const handleConnectWallet = async () => {
    setIsConnecting(true);

    if (phantomProvider) {
      // Real Phantom Connection
      try {
        const response = await phantomProvider.connect();
        const pubKey = response.publicKey.toString();
        setWalletAddress(pubKey);
        console.log("Connected to Phantom:", pubKey);
      } catch (err) {
        console.error("Phantom connection failed or rejected:", err);
      }
    } else {
      // Simulation Fallback
      await new Promise(resolve => setTimeout(resolve, 1000));
      // Generate mock SOL address
      const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
      let addr = '8'; // Solana addrs often start with numbers/letters
      for (let i = 0; i < 4; i++) addr += chars.charAt(Math.floor(Math.random() * chars.length));
      addr += '...';
      for (let i = 0; i < 4; i++) addr += chars.charAt(Math.floor(Math.random() * chars.length));

      setWalletAddress(addr);
      // Optional: Alert user they are in sim mode if they expected Phantom
      // alert("Phantom wallet not detected. Using simulation mode.");
    }

    setIsConnecting(false);
  };

  const handleDisconnect = async () => {
    if (phantomProvider) {
      try {
        await phantomProvider.disconnect();
      } catch (err) {
        console.error("Disconnect error:", err);
      }
    }
    setWalletAddress(null);
  };

  const handleTrendSelect = (topic: string) => {
    setSelectedTopic(topic);
    setStep(Step.DESIGN);
  };

  const handleDesignComplete = (completedDraft: CoinDraft) => {
    setDraft(completedDraft);
    setStep(Step.CONFIG);
  };

  const handleDeploy = (config: Tokenomics) => {
    setTokenomics(config);
    setStep(Step.DEPLOY);
  };

  const handleReset = () => {
    setStep(Step.TRENDS);
    setSelectedTopic('');
    setDraft(null);
    setTokenomics(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-[#0f172a] to-slate-900 text-white selection:bg-purple-500 selection:text-white flex flex-col">
      {/* Header */}
      <header className="p-6 border-b border-slate-800 backdrop-blur-md bg-slate-900/80 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-gradient-to-tr from-purple-600 to-pink-500 rounded-xl flex items-center justify-center shadow-lg shadow-purple-500/20">
                    <Rocket className="text-white w-6 h-6" />
                </div>
                <h1 className="text-xl font-bold tracking-tight hidden md:block">SolaMeme <span className="text-purple-400 font-normal">AI</span></h1>
            </div>

            {/* Status Bar */}
            <div className="hidden lg:flex items-center gap-4 bg-slate-800/50 px-4 py-2 rounded-full border border-slate-700/50 backdrop-blur-sm">
                <div className="flex items-center gap-2 border-r border-slate-700 pr-4">
                    <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                    <span className="text-xs font-mono text-green-400 font-bold uppercase tracking-wider">Pump.fun: Online</span>
                </div>
                <div className="flex items-center gap-2">
                    <Activity className="w-3 h-3 text-blue-400" />
                    <span className="text-xs font-mono text-blue-400 font-bold uppercase tracking-wider">Solscan Indexer: Active</span>
                </div>
            </div>

            <div className="flex items-center gap-4">
                {walletAddress ? (
                  <div className="flex items-center gap-2 bg-slate-800 border border-slate-700 rounded-lg px-4 py-2">
                    <div className="flex items-center gap-2">
                      {phantomProvider ? <Ghost className="w-4 h-4 text-purple-400" /> : <Wallet className="w-4 h-4 text-slate-400" />}
                      <span className="font-mono font-bold text-sm text-white">
                        {walletAddress.length > 15 ? walletAddress.substring(0, 4) + '...' + walletAddress.substring(walletAddress.length - 4) : walletAddress}
                      </span>
                    </div>
                    <button 
                      onClick={handleDisconnect}
                      className="ml-2 pl-2 border-l border-slate-700 text-slate-400 hover:text-red-400 transition-colors"
                      title="Disconnect"
                    >
                      <LogOut className="w-4 h-4" />
                    </button>
                  </div>
                ) : (
                  <button 
                    onClick={handleConnectWallet}
                    disabled={isConnecting}
