        {step === Step.DESIGN && (
          <CoinDesigner 
            initialTopic={selectedTopic} 
            onComplete={handleDesignComplete} 
          />
        )}

        {step === Step.CONFIG && draft && (
          <DeployConfig 
            draft={draft} 
            onDeploy={handleDeploy} 
            onBack={() => setStep(Step.DESIGN)} 
            walletAddress={walletAddress}
            onConnectWallet={handleConnectWallet}
          />
        )}

        {step === Step.DEPLOY && draft && tokenomics && (
          <LaunchPad 
            draft={draft} 
            tokenomics={tokenomics} 
            onReset={handleReset} 
            walletAddress={walletAddress}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="p-6 text-center text-slate-600 text-sm border-t border-slate-800 flex justify-center items-center gap-6">
