import React, { useEffect, useState, useRef } from 'react';
import { CoinDraft, Tokenomics } from '../types';
import { Check, Terminal, ExternalLink, Globe, Shield, Bot, Wallet, Server, Twitter, TrendingUp, DollarSign, Info } from 'lucide-react';

interface Props {
  draft: CoinDraft;
  tokenomics: Tokenomics;
  onReset: () => void;
  walletAddress: string | null;
}

interface Trade {
  type: 'buy' | 'sell';
  amount: number;
  wallet: string;
  txHash: string;
  time: string;
}

const LaunchPad: React.FC<Props> = ({ draft, tokenomics, onReset, walletAddress }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [completed, setCompleted] = useState(false);
  const [contractAddress, setContractAddress] = useState('');

  // Post-Launch State
  const [marketCap, setMarketCap] = useState(5000); // Initial MC in USD
  const [trades, setTrades] = useState<Trade[]>([]);
  const [holders, setHolders] = useState(1);

  const addLog = (msg: string) => setLogs(prev => [...prev, `> ${msg}`]);

  const isSolana = tokenomics.network === 'solana';
  const currency = isSolana ? 'SOL' : 'POL';
  const explorerName = isSolana ? 'Solscan' : 'PolygonScan';
  const dexName = tokenomics.launchMode === 'bonding' ? 'Pump.fun' : (isSolana ? 'Raydium' : 'QuickSwap');

  // Deployment Sequence
  useEffect(() => {
    // Generate a mock contract address based on network
    let mockAddr = '';
    if (isSolana) {
       const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
       for (let i = 0; i < 44; i++) mockAddr += chars.charAt(Math.floor(Math.random() * chars.length));
    } else {
       // Polygon (EVM) address
       const hex = '0123456789abcdef';
       mockAddr = '0x';
       for (let i = 0; i < 40; i++) mockAddr += hex.charAt(Math.floor(Math.random() * hex.length));
    }
    setContractAddress(mockAddr);

    const sequence = async () => {
      addLog(`Initializing ${tokenomics.network.toUpperCase()} deployment sequence...`);
      await new Promise(r => setTimeout(r, 800));

      const networkName = isSolana ? "Solana Mainnet-Beta" : "Polygon PoS Mainnet";
      addLog(`Connecting to ${networkName}...`);
      addLog(`Wallet: ${walletAddress || 'Unknown'}`);
      await new Promise(r => setTimeout(r, 1000));

      // Metadata
      addLog(`Uploading metadata for ${draft.name} ($${draft.ticker})...`);
      addLog(`Metadata Hash: ${isSolana ? 'ipfs://' : '0x'}${mockAddr.substring(0, 12)}...`);
      await new Promise(r => setTimeout(r, 1500));

      // AI VERIFICATION STEP
      addLog(`--- INITIATING AI SMART CONTRACT AUDIT ---`);
      await new Promise(r => setTimeout(r, 800));
      addLog(`AI Agent scanning contract code...`);
      await new Promise(r => setTimeout(r, 1200));
      addLog(`Checking for honeypot logic... [SAFE]`);
      await new Promise(r => setTimeout(r, 500));
      addLog(`Verifying Mint Authority revocation... [VERIFIED]`);
      await new Promise(r => setTimeout(r, 500));
      addLog(`Validating Deployer Signature from ${walletAddress?.substring(0,6)}... [VALID]`);
      await new Promise(r => setTimeout(r, 800));
      addLog(`AUDIT COMPLETE: Score 100/100 (Safe)`);
      addLog(`------------------------------------------`);
      await new Promise(r => setTimeout(r, 1000));


      if (tokenomics.launchMode === 'bonding') {
        addLog(`Initiating Bonding Curve Deployment...`);
        await new Promise(r => setTimeout(r, 1000));
        addLog(`Deploying to Pump.fun protocol...`);
        await new Promise(r => setTimeout(r, 1500));
        addLog(`Minting ${tokenomics.supply.toLocaleString()} tokens to Curve...`);
      } else {
        const contractType = isSolana ? "SPL Token" : "ERC-20 Contract";
        addLog(`Deploying ${contractType}...`);
        await new Promise(r => setTimeout(r, 1000));
        addLog(`Minting ${tokenomics.supply.toLocaleString()} tokens...`);

        await new Promise(r => setTimeout(r, 1000));
        addLog(`Creating ${dexName} Liquidity Pool (${currency}/${draft.ticker})...`);
        addLog(`Adding ${tokenomics.liquidity} ${currency} to pool...`);
        await new Promise(r => setTimeout(r, 2000));
        addLog("Locking LP tokens...");
      }

      await new Promise(r => setTimeout(r, 800));
      addLog(`Indexing contract on ${explorerName} Explorer...`);
      await new Promise(r => setTimeout(r, 800));
      addLog("Verifying contract...");
      addLog("DEPLOYMENT SUCCESSFUL!");
      setCompleted(true);
    };

    sequence();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Post-Launch Simulation Effect (Live Trading)
  useEffect(() => {
    if (!completed) return;

    const interval = setInterval(() => {
        // Simulate a random buy order
        const isBuy = Math.random() > 0.2; // 80% buys to stimulate FOMO
        const amount = Number((Math.random() * 2 + 0.1).toFixed(2));
        const wallet = '...'+Math.random().toString(36).substring(2, 6).toUpperCase();

        const newTrade: Trade = {
            type: isBuy ? 'buy' : 'sell',
            amount,
            wallet,
            txHash: Math.random().toString(36).substring(7),
            time: new Date().toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" })
        };

        setTrades(prev => [newTrade, ...prev].slice(0, 6)); // Keep last 6 trades

        if (isBuy) {
            setMarketCap(prev => prev + (amount * 150)); // Rough simulation of price impact
            setHolders(prev => prev + 1);
        } else {
            setMarketCap(prev => Math.max(1000, prev - (amount * 150)));
        }

    }, 2500); // New trade every 2.5 seconds

    return () => clearInterval(interval);
  }, [completed]);

  const handleShare = () => {
    const text = `Just launched $${draft.ticker} on SolaMeme AI! 🚀\n\nMarket Cap: $${marketCap.toLocaleString()}\nContract: ${contractAddress}\n\nGet in early before we moon! 🌕 #Solana #${draft.ticker}`;
    const url = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleOpenExplorer = () => {
    // Since we haven't actually signed a TX to mainnet, the contract address is simulated.
    // To avoid a 404, we link to the CREATOR'S account to show the wallet connection is real.
    const baseUrl = isSolana ? 'https://solscan.io' : 'https://polygonscan.com';
    // Link to account/address instead of token/address to ensure a valid page load
    const url = `${baseUrl}/account/${walletAddress}`;
    window.open(url, '_blank');
  };

  const handleOpenDex = () => {
    let url = '';
    if (tokenomics.launchMode === 'bonding') {
        url = 'https://pump.fun/board'; 
    } else if (isSolana) {
        url = `https://raydium.io/swap?inputMint=sol&outputMint=${contractAddress}`;
