                    </div>

                    {/* Overlay gradient at bottom */}
                    <div className="absolute bottom-0 left-0 right-0 h-12 bg-gradient-to-t from-slate-900 to-transparent pointer-events-none"></div>
                </div>

                <div className="p-4 bg-slate-800/50 border-t border-slate-800">
                     <button 
                        onClick={handleOpenDex}
                        className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-3 rounded-xl shadow-[0_0_20px_rgba(34,197,94,0.3)] flex items-center justify-center gap-2 transition-all transform hover:scale-[1.02]"
                    >
                        <DollarSign className="w-5 h-5" /> BUY ON {dexName.toUpperCase()}
                     </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default LaunchPad;
